parameters.jsCode:
// Access the output from the nested json structure
const ai_output = $input.item.json.output;

// Get test case info from the original webhook
const test_case = $('Webhook').item.json.body.testCaseName || 'Unknown Test Case';
const room_id = $('Webhook').item.json.body.roomId || '';
const project_id = $('Webhook').item.json.body.projectId || '';
const testcase_id = $('Webhook').item.json.body.testcaseId || '';
const cxtm_url = $('Webhook').item.json.body.cxtmUrl || '';

// Get jobfile_id from CXTM Get UUID node
const jobfile_id = $('CXTM Get UUID').item.json.data[0].jobfile_id || '';

// Truncate to avoid card limits
const truncated_output = ai_output;

return {
  roomId: room_id,
  text: 'AI Analysis Report',
  testCaseName: test_case,
  projectId: project_id,
  testcaseId: testcase_id,
  cxtmUrl: cxtm_url,
  attachments: [
    {
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: {
        '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard',
        version: '1.3',
        body: [
          {
            type: 'TextBlock',
            text: `🤖 AI Test Analysis: ${test_case}`,
            weight: 'Bolder',
            size: 'Large',
            wrap: true
          },
          {
            type: 'TextBlock',
            text: truncated_output,
            wrap: true
          },
          {
            type: 'TextBlock',
            text: 'Was this analysis helpful?',
            weight: 'Bolder',
            separator: true
          }
        ],
        actions: [
          {
            type: 'Action.Submit',
            title: '👍 Helpful',
            data: {feedback: 'helpful', testCase: test_case}
          },
          {
            type: 'Action.Submit',
            title: '👎 Not Helpful',
            data: {feedback: 'not_helpful', testCase: test_case}
          },
          {
            type: 'Action.Submit',
            title: '💬 Needs More Info',
            data: {feedback: 'needs_more_info', testCase: test_case}
          },
          {
            type: 'Action.Submit',
            title: '🎫 Create Jira Ticket',
            data: {
              action: 'create_jira',
              testCase: test_case,
              analysis: truncated_output,
              projectId: project_id,
              testcaseId: testcase_id,
              jobfileId: jobfile_id
            }
          }
        ]
      }
    }
  ]
};

// Format diagnostics analysis for Webex card with Robot code extraction
const ai_output = $input.item.json.output;

// Get test case name
let test_case = '';
let project_id = '';
let testcase_id = '';
let jobfile_id = '';
try {
  test_case = $('Webhook').item.json.body.testCase || $('Webhook').item.json.body.testCaseName || 'Unknown Test Case';
  project_id = $('Webhook').item.json.body.projectId || '';
  testcase_id = $('Webhook').item.json.body.testcaseId || '';
  jobfile_id = $('Webhook').item.json.body.jobfileId || '';
} catch (e) {
  test_case = $input.item.json.testCase || 'Unknown Test Case';
  project_id = $input.item.json.projectId || '';
  testcase_id = $input.item.json.testcaseId || '';
  jobfile_id = $input.item.json.jobfileId || '';
}

// Get room ID
let room_id = '';
try {
  room_id = $('Webhook').item.json.body.roomId || '';
} catch (e) {
  room_id = $input.item.json.roomId || '';
}

// Get Jira key
let jira_key = '';
try {
  jira_key = $('Create an issue').item.json.key || '';
} catch (e) {
  jira_key = '';
}

// Extract Robot Framework code - try multiple patterns
let robot_code = '';
const patterns = [
  /```robot\n([\s\S]*?)```/,
  /```robotframework\n([\s\S]*?)```/,
  /```Robot\n([\s\S]*?)```/,
  /```\n(\*\*\* Settings \*\*\*[\s\S]*?)```/,
  /```(\*\*\* Settings \*\*\*[\s\S]*?)```/
];

for (const pattern of patterns) {
  const match = ai_output.match(pattern);
  if (match) {
    robot_code = match[1].trim();
    break;
  }
}

if (!robot_code) {
  const robotContentMatch = ai_output.match(/(\*\*\* Settings \*\*\*[\s\S]*\*\*\* Keywords \*\*\*[\s\S]*?)(?:\n\n|$)/);
  if (robotContentMatch) {
    robot_code = robotContentMatch[1].trim();
  }
}

// Clean display text
let display_text = ai_output
  .replace(/```(?:robot|robotframework|Robot)?\n?[\s\S]*?```/g, '')
  .trim()
  .substring(0, 2000);

return {
  roomId: room_id,
  text: 'Diagnostic Analysis Report',
  jiraKey: jira_key,
  testCase: test_case,
  projectId: project_id,
  testcaseId: testcase_id,
  robotCode: robot_code,
  jobfileId: jobfile_id,
  attachments: [
    {
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: {
        '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard',
        version: '1.3',
        body: [
          {
            type: 'TextBlock',
            text: `🔬 Diagnostic Results: ${test_case}`,
            weight: 'Bolder',
            size: 'Large',
            wrap: true
          },
          {
            type: 'TextBlock',
            text: display_text,
            wrap: true
          },
          {
            type: 'TextBlock',
            text: '🤖 AI-Generated Fix Code:',
            weight: 'Bolder',
            separator: true,
            spacing: 'Medium'
          },
          {
            type: 'TextBlock',
            text: robot_code || 'No fix code generated',
            wrap: true,
            fontType: 'Monospace',
            size: 'Small'
          }
        ],
        actions: [
          {
            type: 'Action.Submit',
            title: '✅ Apply Recommended Fix',
            style: 'positive',
            data: {
              action: 'apply_fix',
              testCase: test_case,
              robotCode: robot_code,
              jiraKey: jira_key,
              projectId: project_id,
              testcaseId: testcase_id,
              jobfileId: jobfile_id
            }
          },
          {
            type: 'Action.Submit',
            title: '🔄 Reset Device Config',
            data: {
              action: 'reset_device_config',
              testCase: test_case,
              jiraKey: jira_key,
              projectId: project_id,
              testcaseId: testcase_id,
              jobfileId: jobfile_id
            }
          }
        ]
      }
    }
  ]
};

