// Get robot code directly from webhook body
const webhookBody = $('Webhook').item.json.body;
let robotCode = webhookBody?.robotCode || '';

// Fallback if no code found
if (!robotCode) {
  robotCode = `*** Settings ***
Documentation     AI-Generated Fix - Fallback (no code received)

# CXTA
Library  CXTA
Resource  cxta.robot

Library     String
Library     BuiltIn
Library     Collections

Suite Setup     Run Keywords
...             load testbed

Suite Teardown      Run Keywords
...                 Disconnect From All Devices

*** Test Cases ***
Fallback - No Fix Generated
    Log To Console    WARNING: No AI-generated fix code was received
    Log To Console    Please review the diagnostic analysis manually

*** Keywords ***
Placeholder
    Log    No automated fix available
`;
}

const testCase = webhookBody?.testCase || 'test';
const sha = $input.item.json.sha;
const content = Buffer.from(robotCode).toString('base64');

return {
  message: `AI-generated fix for ${testCase}`,
  content: content,
  sha: sha,
  branch: 'master'
};

